--
-- Table structure for table `subject_load_requests`
-- (teachers' subject-load changes, approved by the principal / ADAS)
--

CREATE TABLE IF NOT EXISTS `subject_load_requests` (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `teacher_id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `school_year` varchar(9) NOT NULL,
  `term` tinyint(3) UNSIGNED NOT NULL,
  `proposed` text NOT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  `reviewed_by` int(10) UNSIGNED DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `status` (`status`),
  KEY `teacher_id_school_year_term` (`teacher_id`,`school_year`,`term`),
  KEY `user_id` (`user_id`),
  KEY `reviewed_by` (`reviewed_by`),
  CONSTRAINT `subject_load_requests_reviewer_fk` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `subject_load_requests_teacher_fk` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subject_load_requests_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table structure for table `rma_results`
-- (Rapid Mathematics Assessment, Grades 7-10: entered by Math teachers, shown on the principal dashboard)
--

CREATE TABLE IF NOT EXISTS `rma_results` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `school_year` varchar(9) NOT NULL,
  `period` enum('BoSY','MoSY','EoSY') NOT NULL,
  `grade_level` varchar(20) NOT NULL,
  `section` varchar(100) NOT NULL,
  `sex` enum('Male','Female') NOT NULL,
  `enrolment` smallint(5) unsigned DEFAULT NULL,
  `assessed` smallint(5) unsigned DEFAULT NULL,
  `lvl_not_proficient` smallint(5) unsigned DEFAULT NULL,
  `lvl_low_proficient` smallint(5) unsigned DEFAULT NULL,
  `lvl_nearly_proficient` smallint(5) unsigned DEFAULT NULL,
  `lvl_proficient` smallint(5) unsigned DEFAULT NULL,
  `lvl_highly_proficient` smallint(5) unsigned DEFAULT NULL,
  `cd_number_algebra` decimal(6,2) DEFAULT NULL,
  `cd_measurement_geometry` decimal(6,2) DEFAULT NULL,
  `cd_data_probability` decimal(6,2) DEFAULT NULL,
  `cg_knowing` decimal(6,2) DEFAULT NULL,
  `cg_interpreting` decimal(6,2) DEFAULT NULL,
  `cg_applying` decimal(6,2) DEFAULT NULL,
  `cg_reasoning` decimal(6,2) DEFAULT NULL,
  `mean_score` decimal(6,2) DEFAULT NULL,
  `entered_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rma_results_unique_row` (`school_year`,`period`,`grade_level`,`section`,`sex`),
  KEY `entered_by` (`entered_by`),
  CONSTRAINT `rma_results_entered_by_fk` FOREIGN KEY (`entered_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Table structure for tables `reading_assignments` and `reading_results`
-- (Reading Program / Phil-IRI Filipino & English: encoders assigned by the principal,
--  one row per school year + period + language + section)
--

CREATE TABLE IF NOT EXISTS `reading_assignments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `language` enum('Filipino','English') NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `assigned_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `reading_assignments_unique` (`language`,`user_id`),
  KEY `user_id` (`user_id`),
  KEY `assigned_by` (`assigned_by`),
  CONSTRAINT `reading_assignments_by_fk` FOREIGN KEY (`assigned_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reading_assignments_user_fk` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `reading_results` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `school_year` varchar(9) NOT NULL,
  `period` enum('Beginning','End') NOT NULL,
  `language` enum('Filipino','English') NOT NULL,
  `grade_level` varchar(20) NOT NULL,
  `section` varchar(100) NOT NULL,
  `enrolled_m` smallint(5) unsigned DEFAULT NULL,
  `enrolled_f` smallint(5) unsigned DEFAULT NULL,
  `tested_m` smallint(5) unsigned DEFAULT NULL,
  `tested_f` smallint(5) unsigned DEFAULT NULL,
  `counts` text DEFAULT NULL,
  `status` enum('Draft','Submitted','Approved','Returned') NOT NULL DEFAULT 'Draft',
  `review_note` varchar(500) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `reviewed_by` int(10) unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `reading_results_unique` (`school_year`,`period`,`language`,`grade_level`,`section`),
  KEY `updated_by` (`updated_by`),
  KEY `reviewed_by` (`reviewed_by`),
  CONSTRAINT `reading_results_reviewed_by_fk` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reading_results_updated_by_fk` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

